// A pure specification function: is_ascii_letter returns true
// exactly when c is in 'a'..='z' or 'A'..='Z'.
#[verifier::spec]
fn is_ascii_letter(c: char) -> bool {
    ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z')
}

// A pure specification function that characterizes the problem:
//
//   alone_last_letter(txt) == true
//     ⇔ txt is non‐empty
//        ∧ the last character is an ASCII letter
