//
// We implement it by counting the characters, then looking
// at the last and (if any) second‐last characters via
// `txt.chars().rev().nth(…)`.
#[verifier::spec]
fn alone_last_letter(txt: &str) -> bool {
    let cnt = txt.chars().count();
    if cnt == 0 {
        false
    } else {
        let last = txt.chars().rev().nth(0).unwrap();
        if !is_ascii_letter(last) {
            false
        } else if cnt == 1 {
            true
        } else {
            let prev = txt.chars().rev().nth(1).unwrap();
            prev == ' '
        }
    }
}

